def _unary(self, value, local):     # one input, local slope given
    out = Value(value, (self,))
    def _backward():
        self.grad += local * out.grad
    out._backward = _backward
    return out

def __pow__(self, k):               # k is a plain number
    return self._unary(self.data ** k, k * self.data ** (k - 1))

def tanh(self):
    t = math.tanh(self.data)
    return self._unary(t, 1 - t * t)

def exp(self):
    e = math.exp(self.data)
    return self._unary(e, e)

def log(self):
    return self._unary(math.log(self.data), 1 / self.data)

__radd__ = __add__
__rmul__ = __mul__
def __neg__(self): return self * -1
def __sub__(self, other): return self + (-other)
def __rsub__(self, other): return (-self) + other
def __truediv__(self, other): return self * other ** -1
def __rtruediv__(self, other): return self ** -1 * other
